import{_ as t,o as r,c as a,a2 as l}from"./chunks/framework.Crpw6aS5.js";const c=JSON.parse('{"title":"小巴内特·赫尔兹伯格","description":"","frontmatter":{"title":"小巴内特·赫尔兹伯格","date":"2026-04-13T00:00:00.000Z"},"headers":[],"relativePath":"04_people/小巴内特·赫尔兹伯格.md","filePath":"04_people/小巴内特·赫尔兹伯格.md"}'),o={name:"04_people/小巴内特·赫尔兹伯格.md"};function n(i,e,s,_,d,p){return r(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="小巴内特·赫尔兹伯格-barnett-helzberg-jr" tabindex="-1">小巴内特·赫尔兹伯格（Barnett Helzberg Jr.） <a class="header-anchor" href="#小巴内特·赫尔兹伯格-barnett-helzberg-jr" aria-label="Permalink to &quot;小巴内特·赫尔兹伯格（Barnett Helzberg Jr.）&quot;">​</a></h1><ul><li><strong>角色职位</strong>：赫尔兹伯格钻石店（Helzberg&#39;s Diamonds）创始人及前任所有者</li><li><strong>与巴菲特关系</strong>：1995年将家族企业卖给伯克希尔·哈撒韦</li></ul><h2 id="主要事迹" tabindex="-1">主要事迹 <a class="header-anchor" href="#主要事迹" aria-label="Permalink to &quot;主要事迹&quot;">​</a></h2><p>小巴内特·赫尔兹伯格是赫尔兹伯格钻石店的创始人，赫尔兹伯格钻石店创立于1915年，是美国历史最悠久的珠宝零售品牌之一。赫尔兹伯格家族四代传承，将珠宝店从堪萨斯城一家小店经营成为在全美拥有超过200家门店的连锁珠宝帝国。赫尔兹伯格钻石店以优质钻石、个性化服务和经典款式闻名，深受美国消费者信赖。小巴内特·赫尔兹伯格在掌舵期间，坚守家族价值观，坚持诚信经营，这与巴菲特一贯推崇的商业哲学高度吻合。1995年，赫尔兹伯格将公司以4.34亿美元出售给伯克希尔·哈撒韦，成为伯克希尔珠宝业务板块的核心资产。这笔交易不仅体现了巴菲特对优质家族企业的偏爱，也书写了商业传承的经典案例。</p><h2 id="关键年份事件" tabindex="-1">关键年份事件 <a class="header-anchor" href="#关键年份事件" aria-label="Permalink to &quot;关键年份事件&quot;">​</a></h2><ul><li><strong>1915年</strong>：赫尔兹伯格钻石店由巴内特·赫尔兹伯格（Barnett Helzberg Sr.）在堪萨斯城创立</li><li><strong>20世纪90年代初</strong>：小巴内特·赫尔兹伯格在纽约与巴菲特会面，表达了出售意向</li><li><strong>1995年</strong>：伯克希尔·哈撒韦以4.34亿美元收购赫尔兹伯格钻石店</li></ul><hr><p><em>本档案基于公开信息整理，伯克希尔知识库</em></p>',8)])])}const g=t(o,[["render",n]]);export{c as __pageData,g as default};
